tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/3c-families-offer-probe-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
$PY -c "import storygame,sys; sys.exit(0 if storygame.__file__.startswith('$PWD') else 1)" || { echo "FAIL: not worktree"; exit 1; }
bad=$(git status --porcelain | awk '{print $2}' | grep -v -x -e notes.md -e pytest.out -e scripts/ringer/stage7/3c_families_offer_probe.py -e tests/test_3c_families_offer_probe.py -e bench/variations/stage7-3c-families-offer.json -e tests/test_3c_families_offer.py)
test -z "$bad" || { echo "FAIL: outside ownership: $bad"; exit 1; }
git diff --quiet -- storygame data || { echo "FAIL: storygame/data edited"; exit 1; }
$PY -m pytest -q --no-cov -p no:cacheprovider tests/test_3c_families_offer_probe.py tests/test_3c_families_offer.py tests/test_3c_no_close_arm.py > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
rm -rf /tmp/fo-dry; $PY scripts/ringer/stage7/3c_families_offer_probe.py --samples 12 --dry --out /tmp/fo-dry || exit 1
test -s /tmp/fo-dry/offer.screen.txt || { echo "FAIL: no offer screen"; exit 1; }
(diff /tmp/fo-dry/control.screen.txt /tmp/fo-dry/offer.screen.txt || true) | grep -c '^>' | grep -qx 1 || { echo "FAIL: screens do not differ by one changed line"; exit 1; }
$PY -m ruff check scripts/ringer/stage7/3c_families_offer_probe.py tests/test_3c_families_offer_probe.py && $PY -m ruff format --check scripts/ringer/stage7/3c_families_offer_probe.py tests/test_3c_families_offer_probe.py || exit 1
git add -A -- scripts tests bench/variations; git diff --cached -- scripts tests bench/variations > /home/bcorfman/dev/ringer-work/3c-families-offer-probe.patch; test -s /home/bcorfman/dev/ringer-work/3c-families-offer-probe.patch && echo patch-exported
